// ── Apply patches ────────────────────────────────────────────────────────────
async function run() {
  const tourIds = Object.keys(patches)
  console.log(`\nPatching ${tourIds.length} tours...\n`)

  for (const tourId of tourIds) {
    const replacements = patches[tourId]
    try {
      const tour = await client.fetch(
        `*[_id == $id][0]{ _id, title, itinerary[]{ day, title, description, overnight } }`,
        { id: tourId }
      )
      if (!tour) { console.log(`⚠️  ${tourId} — not found`); continue }

      const newItinerary = tour.itinerary.map(item => {
        const replacement = replacements.find(r => r.day === item.day)
        if (replacement) return { ...item, description: replacement.description }
        return item
      })

      await client.patch(tourId).set({ itinerary: newItinerary }).commit()
      console.log(`✅ ${tour.title}`)
      replacements.forEach(r => console.log(`   ↳ ${r.day} (${r.description.length} chars)`))
    } catch (err) {
      console.error(`❌ ${tourId}: ${err.message}`)
    }
    await new Promise(r => setTimeout(r, 300))
  }

  console.log('\n✅ Done.')
}

run().catch(err => { console.error('❌', err); process.exit(1) })
